DROP TABLE IF EXISTS `payroll_deduction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payroll_deduction` (
  `payroll_deduction_id` int NOT NULL AUTO_INCREMENT,
  `payroll_result_id` int NOT NULL,
  `deduction_type_id` int NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `is_taxable` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`payroll_deduction_id`),
  KEY `fk_payroll_deduction_result_idx` (`payroll_result_id`),
  KEY `fk_payroll_deduction_type _idx` (`deduction_type_id`),
  CONSTRAINT `fk_payroll_deduction_result` FOREIGN KEY (`payroll_result_id`) REFERENCES `payroll_result` (`payroll_result_id`),
  CONSTRAINT `fk_payroll_deduction_type ` FOREIGN KEY (`deduction_type_id`) REFERENCES `deduction_type` (`deduction_type_id`),
  CONSTRAINT `chk_payroll_deduction_amount` CHECK ((`amount` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=3426 DEFAULT CHARSET=utf8mb3;
