DROP TABLE IF EXISTS `payroll_earning`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payroll_earning` (
  `payroll_earning_id` int NOT NULL AUTO_INCREMENT,
  `payroll_result_id` int NOT NULL,
  `earning_type_id` int NOT NULL,
  `amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `created_by_account_id` int NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`payroll_earning_id`),
  KEY `fk_payroll_earning_result_idx` (`payroll_result_id`),
  KEY `fk_payroll_earning_type_idx` (`earning_type_id`),
  CONSTRAINT `fk_payroll_earning_result` FOREIGN KEY (`payroll_result_id`) REFERENCES `payroll_result` (`payroll_result_id`),
  CONSTRAINT `fk_payroll_earning_type` FOREIGN KEY (`earning_type_id`) REFERENCES `earning_type` (`earning_type_id`),
  CONSTRAINT `chk_payroll_earning_amount` CHECK ((`amount` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=477 DEFAULT CHARSET=utf8mb3;
