DROP TABLE IF EXISTS `payrun`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payrun` (
  `pay_run_id` int NOT NULL AUTO_INCREMENT,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `pay_date` date NOT NULL,
  `payroll_type` enum('SEMI_MONTHLY','MONTHLY','WEEKLY','BI_WEEKLY') NOT NULL COMMENT 'default SEMI_MONTHLY',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`pay_run_id`),
  CONSTRAINT `chk_payrun_dates` CHECK ((`end_date` >= `start_date`)),
  CONSTRAINT `chk_payrun_pay_date` CHECK ((`pay_date` >= `end_date`))
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb3;
