--
-- Table structure for table `sss_contribution_rate`
--

DROP TABLE IF EXISTS `sss_contribution_rate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sss_contribution_rate` (
  `sss_rate_id` int NOT NULL AUTO_INCREMENT,
  `deduction_type_id` int NOT NULL,
  `min_salary` decimal(12,2) NOT NULL,
  `max_salary` decimal(12,2) NOT NULL,
  `employee_share` decimal(12,2) NOT NULL,
  `employer_share` decimal(12,2) NOT NULL,
  `effective_start_date` date NOT NULL,
  `effective_end_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`sss_rate_id`),
  KEY `fk_sss_rate_deduction_type_idx` (`deduction_type_id`),
  CONSTRAINT `fk_sss_rate_deduction_type` FOREIGN KEY (`deduction_type_id`) REFERENCES `deduction_type` (`deduction_type_id`),
  CONSTRAINT `chk_sss_effective_dates` CHECK (((`effective_end_date` is null) or (`effective_end_date` >= `effective_start_date`))),
  CONSTRAINT `chk_sss_employee_share` CHECK ((`employee_share` >= 0)),
  CONSTRAINT `chk_sss_employer_share` CHECK ((`employer_share` >= 0)),
  CONSTRAINT `chk_sss_salary_range` CHECK ((`max_salary` >= `min_salary`))
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

