CREATE TABLE `support_ticket` (
  `ticket_id` int NOT NULL AUTO_INCREMENT,
  `employee_id` int NOT NULL,
  `category` enum('PAYROLL','ATTENDANCE','ACCOUNT','SYSTEM','OTHER') NOT NULL,
  `routing_team` enum('HR','PAYROLL','IT','ADMIN') NOT NULL,
  `subject` varchar(150) NOT NULL,
  `description` varchar(1000) NOT NULL,
  `status` enum('OPEN','RESOLVED','CANCELLED') NOT NULL DEFAULT 'OPEN',
  `resolved_by_user_account_id` int DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ticket_id`),
  KEY `fk_support_ticket_employee` (`employee_id`),
  KEY `fk_support_ticket_resolved_by` (`resolved_by_user_account_id`),
  CONSTRAINT `fk_support_ticket_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`employee_id`),
  CONSTRAINT `fk_support_ticket_resolved_by` FOREIGN KEY (`resolved_by_user_account_id`) REFERENCES `user_account` (`user_account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
