INSERT INTO `support_ticket` VALUES (1,10006,'PAYROLL','PAYROLL','Payroll Calculation Inaccurate for June 2026 Pay Period','I would like to report a discrepancy in my payroll for the June 2026 pay period. Upon reviewing my payslip, I noticed that the total salary amount does not match my expected earnings.\n\nDetails:\n\nEmployee Name: [Your Name]\nEmployee ID: [Employee ID]\nPay Period: June 1–15, 2026\nExpected Amount: ₱35,000\nActual Amount Received: ₱31,500\nDifference: ₱3,500\n\nI have verified my attendance records and overtime hours, and they appear to be correct. It seems that either my overtime pay, allowances, or other payroll components may not have been included accurately in the calculation.\n\nPlease investigate this issue and advise on the cause of the discrepancy. I would appreciate a correction and any necessary payroll adjustment at the earliest opportunity.','OPEN',NULL,NULL,'2026-06-15 21:26:55',NULL),(2,10005,'SYSTEM','IT','Payroll System Loading Slowly','The Payroll System takes more than 2 minutes to load after logging in. The issue occurs during peak working hours and affects multiple employees.','OPEN',NULL,NULL,'2026-06-17 19:09:35',NULL),(3,10016,'ATTENDANCE','HR','Incorrect attendance log','My attendance record shows the wrong time-in for my recent workday. Please review my attendance log.','OPEN',NULL,NULL,'2026-06-21 07:31:29',NULL);
/*!40000 ALTER TABLE `support_ticket` ENABLE KEYS */;
UNLOCK TABLES;

