--
-- Table structure for table `user_access_logs`
--

DROP TABLE IF EXISTS `user_access_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_access_logs` (
  `log_id` int NOT NULL AUTO_INCREMENT,
  `user_account_id` int DEFAULT NULL,
  `action` varchar(50) NOT NULL,
  `details` varchar(255) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `device_info` varchar(255) DEFAULT NULL,
  `logged_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `target_type` varchar(50) DEFAULT NULL,
  `target_id` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`log_id`),
  KEY `fk_logs_user_idx` (`user_account_id`),
  KEY `idx_user_access_logs_target` (`target_type`,`target_id`),
  CONSTRAINT `fk_user_access_logs_user_account` FOREIGN KEY (`user_account_id`) REFERENCES `user_account` (`user_account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=584 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

